package com.yeyamo_mobile.api.gamification_service.infrastructure.web;import java.util.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import com.yeyamo_mobile.api.gamification_service.application.GamificationService;import com.yeyamo_mobile.api.gamification_service.domain.*;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.security.SecurityRequirement;
@RestController@RequestMapping("/api/v1/me")public class GamificationController{private final GamificationService service;public GamificationController(GamificationService s){service=s;}@GetMapping("/xp")@Operation(summary="Read my XP and level",security=@SecurityRequirement(name="bearerAuth"))public Progress xp(Authentication a){return service.view(a.getName()).progress();}@GetMapping("/badges")public List<Badge>badges(Authentication a){return service.view(a.getName()).badges();}@GetMapping("/passport")public List<PassportStamp>passport(Authentication a){return service.view(a.getName()).passport();}@GetMapping("/streaks")public StreakResponse streaks(Authentication a){Progress p=service.view(a.getName()).progress();return new StreakResponse(p.currentStreak(),p.longestStreak(),p.lastActivityDate());}@GetMapping("/rewards")public List<Reward>rewards(Authentication a){return service.view(a.getName()).rewards();}@PostMapping("/rewards/{id}/claim")public Reward claim(Authentication a,@PathVariable UUID id,@RequestHeader(value="X-Correlation-Id",required=false)String correlation){return service.claim(a.getName(),id,correlation);}public record StreakResponse(int current,int longest,java.time.LocalDate lastActivityDate){}}
